  ('0f41e9ac-171e-418a-a4b6-bf427a050b66'::uuid, 'hymnal', 'approved', 256, 'Dicséretek', 'Erős vár a mi Istenünk', array['reformáció', 'bizalom', 'Luther']::text[], $hymnal${"number":256,"title":"Erős vár a mi Istenünk","book":"Dicséretek","reference":"Zsolt 46","origin":{"place":"Németország","year":1529},"tune":{"name":"Ein feste Burg","origin":{"place":"Németország","year":1529}},"originalKey":"C","timeSignature":"4/4","verses":[{"number":1,"hasNotation":true,"lines":[{"text":"Erős vár a mi Istenünk,","chords":[{"chord":"C","position":0},{"chord":"G","position":10},{"chord":"Am","position":16},{"chord":"C","position":22}]},{"text":"Jó fegyverünk és pajzsunk.","chords":[{"chord":"F","position":0},{"chord":"C","position":8},{"chord":"G","position":16},{"chord":"C","position":22}]},{"text":"Ha ő velünk, ki ellenünk?","chords":[{"chord":"Am","position":0},{"chord":"Em","position":10},{"chord":"F","position":16},{"chord":"C","position":22}]},{"text":"Az Úr a mi oltalmunk!","chords":[{"chord":"G","position":0},{"chord":"Am","position":6},{"chord":"F","position":12},{"chord":"G","position":16},{"chord":"C","position":20}]}]},{"number":2,"hasNotation":false,"plainText":"Ha e világ mind ördög volna, Elnyelni kész, de ne félj! A Krisztus harcol mellettünk, S győz a hittel, ki felveszi."},{"number":3,"hasNotation":false,"plainText":"Az ige áll az erős Isten, Nincs más segítség nekünk. Hadd vesszen el kincs, test és vér, Országunk megmarad."}],"tags":["reformáció","bizalom","Luther"],"notation":{"originalKey":"C","timeSignature":"4/4","showTimeSignature":false,"verses":[{"number":1,"measures":[{"beats":[{"pitch":"C4","duration":"quarter","syllables":["E-","Ha"]},{"pitch":"C4","duration":"eighth","syllables":["rős","ő"]},{"pitch":"C4","duration":"eighth","syllables":["vár","ve-"]},{"pitch":"B3","duration":"quarter","syllables":["a","lünk,"]},{"pitch":"A3","duration":"quarter","syllables":["mi","ki"]},{"pitch":"B3","duration":"quarter","syllables":["Is-","el-"]},{"pitch":"C4"